"""Implementation of actions for the Machine Characterization UI in the Mosaiq application"""

from .objects.mosaiq_core_objects import MosaiqCoreObjects
from .objects.mosaiq_machine_characterization_objects import MachineCharact
from interops.libraries.squish_actions import CommonActions
from interops.libraries.desktop import decorators as deco
from interops.libraries.squish_actions.constants import MOSAIQ_APP_NAME
import time

def __find_location_directory_window() -> bool:
    """Searches for the main Location Directory window within Machine Characterization workflow. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the machine_characterization.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(MosaiqCoreObjects.locationDirectory_Window) is not None else False

def __find_location_directory_add_locations_window() -> bool:
    """Searches for the Add Locations UI window within Machine Characterization workflow. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the machine_characterization.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(MosaiqCoreObjects.locDirectory_Location_Window) is not None else False

def __find_machine_characterization_window() -> bool:
    """Searches for the main Machine Characterization window within Machine Characterization workflow. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the machine_characterization.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(MachineCharact.Main_Window) is not None else False

def __find_machine_characterization_import_window() -> bool:
    """Searches for the Import UI window within Machine Characterization workflow. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the machine_characterization.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(MachineCharact.Import_Window) is not None else False

def __find_machine_characterization_add_editor_window() -> bool:
    """Searches for the Add Characterization Editor UI window within Machine Characterization workflow. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the machine_characterization.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(MachineCharact.Add_Characterization_Editor_Window) is not None else False

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def close_location_directories() -> None:
    """Locates the Location Directory main window > clicks the Close button in the top menu bar.
    """
    if __find_location_directory_window():
        CommonActions.left_click_object(MosaiqCoreObjects.locationDirectory_TopBarItem_Close_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def open_add_new_location() -> None:
    """Locates the Location Directory main window > clicks the Add button in the top menu bar >
    waits for the Add Location UI window to appear.
    """
    if __find_location_directory_window():
        CommonActions.left_click_object(MosaiqCoreObjects.locationDirectory_TopBarItem_Add_Button)
        CommonActions.find_object(MosaiqCoreObjects.locDirectory_Location_Window)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def type_location_details_name(locationName: str) -> None:
    """Locates the Add Location UI window > types in a given location name into the Location Name text box.

    :param str locationName: Location Name string to be typed into the location name text box
    """
    if __find_location_directory_add_locations_window():
        CommonActions.type_in_textfield(MosaiqCoreObjects.locDirectory_Location_Name_TextBox, locationName)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_location_details_category(locationCategory: str) -> None:
    """Locates the Add Location UI window > clicks the Location Category dropdown button > searches for a given Location Category
    in the dropdown window > selects that option if found.

    :param str locationCategory: Location Category string to be searched for in the dropdown window
    """
    if __find_location_directory_add_locations_window():
        CommonActions.left_click_object(MosaiqCoreObjects.locDirectory_Location_Category_Dropdown_Button)
        categoryItem = CommonActions.get_object_by_ocr_text_in_object(CommonActions.find_object((MosaiqCoreObjects.locDirectory_Location_Type_Dropdown_Window)), locationCategory)
        CommonActions.left_click_object_no_move(categoryItem)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_location_details_type(locationType: str) -> None:
    """Locates the Add Location UI window, clicks the Location Type dropdown button, searches for a given Location Type
    in the dropdown window and selects that option if found.

    :param str locationType: Location Type string to be searched for in the dropdown window
    """
    if __find_location_directory_add_locations_window():
        CommonActions.left_click_object(MosaiqCoreObjects.locDirectory_Location_Type_Dropdown_Button)
        typeItem = CommonActions.get_object_by_ocr_text_in_object(CommonActions.find_object((MosaiqCoreObjects.locDirectory_Location_Type_Dropdown_Window)), locationType)
        CommonActions.left_click_object_no_move(typeItem)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def save_location_details() -> None:
    """Locates the Add Location UI window and clicks the Save button in the top menu bar.
    """
    if __find_location_directory_add_locations_window():
        CommonActions.left_click_object(MosaiqCoreObjects.locDirectory_Location_TopBarItem_Save_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def open_import_machine_characterization() -> None:
    """Locates the Machine Characterization main window > clicks the Import button >
    waits for the Import UI window to appear.
    """
    if __find_machine_characterization_window():
        CommonActions.left_click_object(MachineCharact.Import_Button)
        CommonActions.find_object(MachineCharact.Import_Window)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_pc_desktop_import_path() -> None:
    """Locates the Import UI window > clicks the Open File Browser button, double clicks the "This PC -> Desktop" browser tree item >
    then clicks the OK button on the File Browser dialog.
    """
    if __find_machine_characterization_import_window():
        CommonActions.left_click_object(MachineCharact.Import_Path_Open_Browser_Button)
        CommonActions.double_click_object(MachineCharact.BrowseFolder_This_PC_Desktop_TreeItem)
        CommonActions.left_click_object(MachineCharact.BrowseFolder_OK_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def open_import_file_dropdown() -> None:
    """Locates the Import UI window > clicks the Import File dropdown button > waits for the dropdown window to appear.
    """
    if __find_machine_characterization_import_window():
        CommonActions.left_click_object(MachineCharact.Import_File_Dropdown)
        CommonActions.find_object(MachineCharact.Import_File_Dropdown_Window)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_import_file_from_dropdown(fileName: str) -> None:
    """Locates the Import File dropdown window > searches for a given fileName text string object with that dropdown window >
    then clicks that object.

    :param str fileName: String of File Name to be located
    """
    CommonActions.find_object(MachineCharact.Import_File_Dropdown_Window)
    importFile = CommonActions.get_object_by_ocr_text_in_object(CommonActions.find_object((MachineCharact.Import_File_Dropdown_Window)), fileName)
    CommonActions.left_click_object_no_move(importFile)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_template_import_ok_button() -> None:
    """Locates the Import UI window > clicks the OK button.
    """
    if __find_machine_characterization_import_window():
        CommonActions.left_click_object(MachineCharact.Import_OK_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def open_add_machine_characterization() -> None:
    """Locates the Machine Characterization main window > clicks the Add button >
    waits for the Add Characterization Editor window to appear.
    """
    if __find_machine_characterization_window():
        CommonActions.left_click_object(MachineCharact.Add_Button)
        CommonActions.find_object(MachineCharact.Add_Characterization_Editor_Window)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_machine_as_characterization_type() -> None:
    """Locates the Add Characterization Editor UI window > clicks the Characterization Type dropdown >
    then locates and clicks the "Machine" option.
    """
    if __find_machine_characterization_add_editor_window():
        CommonActions.left_click_object(MachineCharact.Add_Characterization_Type_Dropdown)
        characterizationType = CommonActions.get_object_by_ocr_text_in_object(CommonActions.find_object((MachineCharact.Add_Characterization_Type_Dropdown_Window)), "Machine")
        CommonActions.left_click_object_no_move(characterizationType)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_machine(machineName: str) -> None:
    """Locates the Add Characterization Editor UI window > clicks the Add Characterization Machine dropdown >
    locates a given machineName string > clicks successfully found machineName string.

    :param str machineName: Machine Name string to be located and clicked.
    """
    if __find_machine_characterization_add_editor_window():
        CommonActions.left_click_object(MachineCharact.Add_Characterization_Machine_Dropdown)
        machineItem = CommonActions.get_object_by_ocr_text_in_object(CommonActions.find_object((MachineCharact.Add_Characterization_Machine_Dropdown_Window)), machineName)
        CommonActions.left_click_object_no_move(machineItem)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def open_pick_reference_characterizations_window() -> None:
    """Locates the Add Characterization Editor UI window > clicks the Characterization Reference button >
    waits for the Pick Reference Characterization window to appear.
    """
    if __find_machine_characterization_add_editor_window():
        CommonActions.left_click_object(MachineCharact.Add_Characterization_Reference_Button)
        CommonActions.find_object(MachineCharact.pickReference_Characterizations_Window)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_reference_template(templateName: str) -> None:
    """Locates the Pick Reference Characterization UI window > locates a given templateName string in the Reference Pane object >
    then clicks the line in the Reference pane where that string is found.

    :param str templateName: Reference Template string to be located in the Reference pane object
    """
    CommonActions.find_object(MachineCharact.pickReference_Characterizations_Window)
    templateLine = CommonActions.get_object_by_ocr_text_in_object(CommonActions.find_object((MachineCharact.pickReference_Characterizations_Reference_Pane)), templateName)
    CommonActions.left_click_object_no_move(templateLine)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_pick_reference_select_button() -> None:
    """Locates the Pick Reference Characterization UI window > clicks the Select button.
    """
    CommonActions.find_object(MachineCharact.pickReference_Characterizations_Window)
    CommonActions.left_click_object(MachineCharact.pickReference_Characterizations_Reference_Select_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_copy_all_button() -> None:
    """Locates the Add Characterization Editor UI window > clicks the Copy All button.
    """
    if __find_machine_characterization_add_editor_window():
        CommonActions.left_click_object(MachineCharact.Add_Characterization_All_Button)
        time.sleep(2)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_add_machine_ok_button() -> None:
    """Locates the Add Characterization Editor UI window > clicks the OK button.
    """
    if __find_machine_characterization_add_editor_window():
        CommonActions.left_click_object(MachineCharact.Add_Characterization_Ok_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_machine_characterization_approve_button() -> None:
    """Locates the Machine Characterization main window > clicks the Approve button
    """
    if __find_machine_characterization_window():
        CommonActions.left_click_object(MachineCharact.Approve_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_option_in_characterization_view_list(option: str) -> None:
    """Locates the Machine Characterization main window > locates a give option string in the View List object >
    then clicks the screen area object where that string is found.

    :param str option: Option string to be located within the View List object
    """
    if __find_machine_characterization_window():
        optionLine = CommonActions.get_object_by_ocr_text_in_object(CommonActions.find_object((MachineCharact.View_List)), option)
        CommonActions.click_screen_area_object(optionLine)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def enter_approval_password(password: str) -> None:
    """Locates the Characterization Approval UI window > types in a given password into the Password text box.

    :param str password: Password string to be typed into the Password text box.
    """
    CommonActions.find_object(MachineCharact.approval_Window)
    CommonActions.type_in_textfield(MachineCharact.approval_Password_Box, password)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_approval_ok_button() -> None:
    """Locates the Characterization Approval UI window > clicks the OK button.
    """
    CommonActions.find_object(MachineCharact.approval_Window)
    CommonActions.left_click_object(MachineCharact.approval_OK_Button)